css:
.projsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a37;
    background: linear-gradient(180deg, #fbf7f0 0%, #f3ede2 100%);
    border-radius: 18px;
}

.projsim-container * {
    box-sizing: border-box;
}

.projsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14302e 0%, #1d4a44 55%, #2a6a5e 100%);
    color: #f4efe6;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0f2422;
    box-shadow: 0 14px 34px rgba(20, 48, 46, 0.28);
}

.projsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fdfaf3;
}

.projsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4b94e;
    background: rgba(244, 185, 78, 0.14);
    border: 1px solid rgba(244, 185, 78, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.projsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7e3df;
}

.projsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a5b54;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.projsim-period-counter #currentDay,
.projsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1d4a44;
}

.projsim-round-name {
    background: #1d4a44;
    color: #f4efe6;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.projsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a1f;
    background: rgba(214, 121, 47, 0.14);
    border: 1px solid rgba(214, 121, 47, 0.35);
    padding: 4px 12px;
    border-radius: 999px;
}

.projsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.projsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6ddcf;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.06);
    border-top: 4px solid #cbb994;
}

.projsim-card-runway { border-top-color: #2a6a5e; }
.projsim-card-delivery { border-top-color: #2f6fb0; }
.projsim-card-margin { border-top-color: #d6792f; }
.projsim-card-conviction { border-top-color: #8a5cc4; }

.projsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7b8a82;
}

.projsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a37;
    font-variant-numeric: tabular-nums;
}

.projsim-card-runway .projsim-value { color: #2a6a5e; }
.projsim-card-delivery .projsim-value { color: #2f6fb0; }
.projsim-card-margin .projsim-value { color: #d6792f; }
.projsim-card-conviction .projsim-value { color: #8a5cc4; }

.projsim-sublabel {
    font-size: 0.76rem;
    color: #8a9690;
    line-height: 1.35;
}

.projsim-runway-danger { border-top-color: #c0392b; }
.projsim-runway-danger .projsim-value { color: #c0392b; }
.projsim-runway-safe { border-top-color: #2a6a5e; }
.projsim-runway-safe .projsim-value { color: #2a6a5e; }

.projsim-margin-low .projsim-value { color: #c0392b; }
.projsim-margin-high .projsim-value { color: #2a6a5e; }

.projsim-burn-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f2a37;
    border: 1px solid #14202c;
    color: #e8ede9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.projsim-burn-bar #burnDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f4b94e;
}

.projsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2a6a5e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #e6ddcf;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.06);
}

.projsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.projsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14302e;
    margin-bottom: 6px;
}

.projsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4842;
}

.projsim-briefing-text strong { color: #2a6a5e; }
.projsim-briefing-text em { color: #9a4a1f; font-style: italic; }

.projsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6ddcf;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.06);
}

.projsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14302e;
    border-bottom: 2px solid #efe7d8;
    padding-bottom: 8px;
}

.projsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3a33;
    margin: 14px 0 6px;
}

.projsim-container select,
.projsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3c8b5;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfbf6;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.projsim-container select:focus,
.projsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a6a5e;
    box-shadow: 0 0 0 3px rgba(42, 106, 94, 0.16);
}

.projsim-container select option {
    background-color: #fdfbf6;
    color: #1f2a37;
}

.projsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2a6a5e;
}

.projsim-range-readout,
.projsim-mix-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a5b54;
    margin-top: 4px;
}

.projsim-range-readout span:last-child,
.projsim-mix-readout span:nth-child(2) {
    color: #2a6a5e;
    font-weight: 800;
}

.projsim-hint {
    font-size: 0.8rem;
    color: #8a9690;
    margin-top: 4px;
    line-height: 1.4;
}

.projsim-role-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.projsim-role-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #faf6ee;
    border: 1px solid #e6ddcf;
    border-radius: 9px;
    padding: 8px 12px;
}

.projsim-role-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c3a33;
}

.projsim-role-row select {
    width: 140px;
    flex: 0 0 140px;
}

.projsim-shock {
    background: rgba(192, 57, 43, 0.08);
    border: 1px solid rgba(192, 57, 43, 0.35);
    border-left: 5px solid #c0392b;
    color: #8a2820;
    font-weight: 600;
    font-size: 0.9rem;
    line-height: 1.5;
    padding: 12px 14px;
    border-radius: 9px;
    margin: 6px 0 4px;
}

.projsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.projsim-container .btn-primary {
    background: linear-gradient(135deg, #1d4a44 0%, #2a6a5e 100%);
    border: none;
    color: #f4efe6;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(29, 74, 68, 0.28);
}

.projsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.projsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3c8b5;
    color: #6b7a72;
    background: transparent;
}

.projsim-coach {
    background: linear-gradient(135deg, #fff6e6 0%, #fdeccf 100%);
    color: #4a3a22;
    border: 1px solid #ecd6a8;
    border-left: 5px solid #f4b94e;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.06);
}

.projsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9a4a1f;
    margin-bottom: 8px;
}

.projsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.projsim-coach-body strong { color: #1d4a44; }
.projsim-coach-body em { color: #9a4a1f; font-style: italic; }

.projsim-history,
.projsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6ddcf;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.06);
}

.projsim-history h3,
.projsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14302e;
}

.projsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c3a33;
}

.projsim-container table#usfHistoryTable th {
    background: #faf6ee;
    color: #1d4a44;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e6ddcf;
}

.projsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe7d8;
    color: #3a4842;
}

.projsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf8f1;
}

.projsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .projsim-container {
        padding: 14px;
    }
    .projsim-header h1 {
        font-size: 1.7rem;
    }
    .projsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .projsim-value {
        font-size: 2rem;
    }
    .projsim-clock {
        margin-left: 0;
    }
    .projsim-period-counter {
        font-size: 0.88rem;
    }
    .projsim-burn-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .projsim-role-row {
        flex-wrap: wrap;
    }
    .projsim-role-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .projsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.pe-cm { font-family: inherit; color: #1f2a37; padding: 4px 2px 2px; }
.pe-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f5f2ea,#e6ddcf); border-radius: 14px; border: 1px solid #ddd2c0; }
.pe-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #2a6a5e; }
.pe-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #7c8681; margin-left: 2px; }
.pe-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #7c8681; margin-top: 6px; }
.pe-cm-grade { font-size: 1.16rem; font-weight: 700; color: #1d4a44; margin-top: 8px; }
.pe-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.pe-cm-badge-pass { background: #cce9df; color: #1d5a4d; }
.pe-cm-badge-miss { background: #f6d9d4; color: #a5341f; }
.pe-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.pe-cm-kpi { background: #ffffff; border: 1px solid #e6ddcf; border-top: 3px solid #2a6a5e; border-radius: 10px; padding: 12px 8px; text-align: center; }
.pe-cm-k-runway { border-top-color: #2a6a5e; }
.pe-cm-k-delivery { border-top-color: #2f6fb0; }
.pe-cm-k-margin { border-top-color: #d6792f; }
.pe-cm-k-conviction { border-top-color: #8a5cc4; }
.pe-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1f2a37; line-height: 1.05; }
.pe-cm-k-runway .pe-cm-kpi-val { color: #2a6a5e; }
.pe-cm-k-delivery .pe-cm-kpi-val { color: #2f6fb0; }
.pe-cm-k-margin .pe-cm-kpi-val { color: #b4601f; }
.pe-cm-k-conviction .pe-cm-kpi-val { color: #8a5cc4; }
.pe-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #3f4a47; margin-top: 5px; }
.pe-cm-kpi-sub { font-size: .64rem; color: #8a938f; margin-top: 2px; line-height: 1.25; }
.pe-cm-insights { margin: 16px 2px 6px; }
.pe-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #7c8681; margin: 0 0 8px; font-weight: 700; }
.pe-cm-insights ul { margin: 0; padding-left: 18px; }
.pe-cm-insights li { font-size: .86rem; line-height: 1.5; color: #2b3a37; margin-bottom: 7px; }
.pe-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #e6ddcf; font-size: .72rem; color: #8a938f; text-align: center; font-style: italic; }
@media (max-width: 640px) { .pe-cm-kpis { grid-template-columns: repeat(2,1fr); } .pe-cm-scorenum { font-size: 2.6rem; } }

