(function() {
    'use strict';

    class ProjectEconomyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Project Economy`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Foundry & Field Ltd.). All money in EUR thousands unless noted.
            this.CASH = 1300;            // EUR 1.3M cash on hand
            this.BASE_BURN = 145;        // EUR 145,000 baseline monthly burn
            this.EMP_COST = 8.5;         // EUR 8,500 / month loaded employee
            this.FREE_COST = 11.5;       // EUR 11,500 / month freelancer
            this.EMP_TAIL = 8.5 * 4;     // ~4 months' notice/severance tail per surge employee (EUR 34k)
            this.SURGE_ROLES = 5;        // 5 extra senior roles to staff the ~2x surge
            this.CONTRACT = 1200;        // EUR 1.2M contract
            this.MONTHS = 6;             // 6-month build
            this.TARGET_MARGIN = 38;     // 38% target project margin
            this.CLIFF = 5;              // runway cliff: under 5 months

            // The "core" roles whose knowledge must be owned (architect + backend).
            this.CORE_ROLES = [`roleLead`, `roleBackend`];
            this.ALL_ROLES = [`roleLead`, `roleBackend`, `roleData`, `roleFrontend`, `roleQa`];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    runway: 9.0,             // months of cash left
                    delivery: 55,            // delivery confidence vs the fixed go-live (0-100)
                    margin: 38,              // project margin % (target 38)
                    conviction: 40,          // asset-light / project-economy thesis proven (0-100)
                    burn: this.BASE_BURN,    // effective monthly burn during the build (EUR 000)
                    empCount: 0,             // surge roles staffed as employees
                    freeCount: 0,            // surge roles staffed as freelancers
                    coreOwned: 0,            // how many of the 2 core roles are permanent
                    tailLiability: 0,        // committed notice/severance tail (EUR 000)
                    overHired: false,
                    hollowedCore: false,
                    cashCrisis: false,
                    runwayHistory: [9.0],
                    deliveryHistory: [55],
                    convictionHistory: [40],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately wrong-leaning mix — a blind
                // click-through must not auto-win (all-freelance, rate-driven, end-loaded cash, hold the team).
                state.decisions = {
                    gap: `under`,
                    split: `allsurge`,
                    runwayDiscipline: 50,
                    roleLead: `freelance`,
                    roleBackend: `freelance`,
                    roleData: `freelance`,
                    roleFrontend: `freelance`,
                    roleQa: `freelance`,
                    test: `rate`,
                    billing: `endload`,
                    knowledge: `none`,
                    buffer: 0,
                    flex: `hold`,
                    metric: `revenue`,
                    pitchConviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const val = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                const g = val(`gapInput`); if (g) decisions.gap = g;
                const s = val(`splitInput`); if (s) decisions.split = s;
                const rd = document.getElementById(`runwayDisciplineInput`);
                if (rd) decisions.runwayDiscipline = parseInt(rd.value, 10);
                if (!Number.isFinite(decisions.runwayDiscipline) || decisions.runwayDiscipline < 0 || decisions.runwayDiscipline > 100) {
                    warn(`warn_discipline_range`); return false;
                }
            } else if (round === 2) {
                this.ALL_ROLES.forEach((r) => {
                    const v = val(r + `Input`);
                    if (v) decisions[r] = v;
                });
                const t = val(`testInput`); if (t) decisions.test = t;
                const bad = this.ALL_ROLES.some((r) => decisions[r] !== `employee` && decisions[r] !== `freelance`);
                if (bad) { warn(`warn_role_value`); return false; }
            } else if (round === 3) {
                const b = val(`billingInput`); if (b) decisions.billing = b;
                const k = val(`knowledgeInput`); if (k) decisions.knowledge = k;
                const bf = document.getElementById(`bufferInput`);
                if (bf) decisions.buffer = parseFloat(bf.value);
                if (!Number.isFinite(decisions.buffer) || decisions.buffer < 0 || decisions.buffer > 600) {
                    warn(`warn_buffer_range`); return false;
                }
            } else if (round === 4) {
                const f = val(`flexInput`); if (f) decisions.flex = f;
                const m = val(`metricInput`); if (m) decisions.metric = m;
                const pc = document.getElementById(`pitchConvictionInput`);
                if (pc) decisions.pitchConviction = parseInt(pc.value, 10);
                if (!Number.isFinite(decisions.pitchConviction) || decisions.pitchConviction < 0 || decisions.pitchConviction > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let runwayDelta = 0, deliveryDelta = 0, marginDelta = 0, convictionDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the capacity gap and the demand shape (baseline vs surge).
                switch (d.gap) {
                    case `double`: deliveryDelta += 6; convictionDelta += 6; coachKey = `coach_r1_double`; break;
                    case `under`: deliveryDelta -= 10; convictionDelta -= 4; coachKey = `coach_r1_under`; break;
                    case `permanent`: convictionDelta -= 6; ds.overHired = true; coachKey = `coach_r1_permanent`; break;
                }
                switch (d.split) {
                    case `mixed`: convictionDelta += 8; deliveryDelta += 2; if (d.gap === `double`) coachKey = `coach_r1_sharp`; break;
                    case `allsurge`: convictionDelta -= 4; deliveryDelta -= 2; coachKey = `coach_r1_allsurge`; break;
                    case `allbaseline`: convictionDelta -= 6; coachKey = `coach_r1_allbaseline`; break;
                }
                // Runway discipline: treating runway as the binding constraint.
                if (d.runwayDiscipline >= 60) { convictionDelta += 5; }
                else if (d.runwayDiscipline <= 25) { convictionDelta -= 6; coachKey = `coach_r1_nodiscipline`; }

                summaryKey = (d.gap === `double` && d.split === `mixed`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // THE CORE DECISION: the employee/freelance mix across the 5 surge roles.
                let emp = 0, free = 0, coreOwned = 0;
                this.ALL_ROLES.forEach((r) => {
                    if (d[r] === `employee`) emp++; else free++;
                });
                this.CORE_ROLES.forEach((r) => { if (d[r] === `employee`) coreOwned++; });
                ds.empCount = emp;
                ds.freeCount = free;
                ds.coreOwned = coreOwned;
                ds.tailLiability = Math.round(emp * this.EMP_TAIL * 10) / 10;

                // Effective monthly surge cost added to the base burn.
                const surgeCost = emp * this.EMP_COST + free * this.FREE_COST;
                ds.burn = Math.round((this.BASE_BURN + surgeCost) * 10) / 10;

                // Runway during the build = cash / effective burn. (Client cash phasing handled in R3.)
                const newRunway = this.CASH / ds.burn;
                runwayDelta = Math.round((newRunway - ds.runway) * 10) / 10;

                // Margin: contract revenue ~200/mo; freelance premium compresses margin,
                // employees improve it (per-month cheaper) — the headline-rate illusion.
                const monthlyRev = this.CONTRACT / this.MONTHS; // 200
                marginDelta = Math.round((emp * 1.6 - free * 1.0));

                // Delivery: new EMPLOYEE hires carry ramp-up risk (50% productive for 6 weeks on a fixed deadline);
                // FREELANCED CORE roles carry knowledge-walkout risk at month six.
                deliveryDelta -= emp * 2;                 // ramp-up drag on a fixed go-live
                const coreFreelanced = this.CORE_ROLES.length - coreOwned;
                deliveryDelta -= coreFreelanced * 5;      // owner of the core walks out at handover

                // Conviction (the asset-light thesis): own the core, rent the surge.
                convictionDelta += coreOwned * 7;          // owned strategic capability
                const contextFreelanced = (this.SURGE_ROLES - this.CORE_ROLES.length) - 0;
                // reward renting the 3 contextual roles
                let contextRented = 0;
                [`roleData`, `roleFrontend`, `roleQa`].forEach((r) => { if (d[r] === `freelance`) contextRented++; });
                convictionDelta += contextRented * 3;

                // Classic-error penalties baked into the math.
                if (emp >= 5) { ds.overHired = true; runwayDelta -= 0.4; convictionDelta -= 8; coachKey = `coach_r2_allemp`; }
                else if (free >= 5) { ds.hollowedCore = true; deliveryDelta -= 6; convictionDelta -= 6; coachKey = `coach_r2_allfree`; }
                else if (coreOwned === 2 && contextRented >= 2) { coachKey = `coach_r2_blend`; }
                else { coachKey = `coach_r2_partial`; }

                // The four-test rationale.
                switch (d.test) {
                    case `corecontext`: convictionDelta += 8; deliveryDelta += 3; if (coreOwned === 2 && contextRented >= 2) coachKey = `coach_r2_corecontext`; break;
                    case `rate`: marginDelta += 1; convictionDelta -= 6; if (emp >= 4) coachKey = `coach_r2_rate`; break;
                    case `lean`: convictionDelta -= 4; if (free >= 4) coachKey = `coach_r2_lean`; break;
                }

                summaryKey = (coreOwned === 2 && contextRented >= 2 && d.test === `corecontext`) ? `sum_r2_good` :
                             (emp >= 5 ? `sum_r2_allemp` : (free >= 5 ? `sum_r2_allfree` : `sum_r2_weak`));
            } else if (round === 3) {
                // Operationalise: phase client cash against payroll, capture knowledge.
                switch (d.billing) {
                    case `milestones`: runwayDelta += 0.8; convictionDelta += 5; coachKey = `coach_r3_milestones`; break;
                    case `even`: runwayDelta += 0.2; break;
                    case `endload`: runwayDelta -= 0.9; ds.cashCrisis = true; convictionDelta -= 4; coachKey = `coach_r3_endload`; break;
                }
                switch (d.knowledge) {
                    case `paired`: deliveryDelta += 10; convictionDelta += 6; if (ds.hollowedCore) ds.hollowedCore = false; coachKey = (d.billing === `milestones`) ? `coach_r3_solid` : `coach_r3_paired`; break;
                    case `docs`: deliveryDelta += 3; break;
                    case `none`: deliveryDelta -= 6; convictionDelta -= 4; coachKey = `coach_r3_noknow`; break;
                }
                // Ring-fenced cash buffer protects the runway in the milestone gap.
                if (d.buffer > 0) {
                    runwayDelta += Math.min(0.8, d.buffer / 400);
                    if (ds.cashCrisis && d.buffer >= 200) { ds.cashCrisis = false; }
                }
                if (d.billing === `endload` && d.buffer < 200) {
                    runwayDelta -= 0.4; coachKey = `coach_r3_endload`;
                }

                summaryKey = (d.billing !== `endload` && d.knowledge === `paired`) ? `sum_r3_good` :
                             (d.billing === `endload` && d.buffer < 200 ? `sum_r3_cash` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pipeline shock: the EUR 500k Q3 follow-on is delayed indefinitely.
                // The durable demand that justified permanent surge hires just shrank.
                switch (d.flex) {
                    case `flexdown`:
                        // Use the reversibility you built in — only real if you actually rented capacity.
                        if (ds.freeCount >= 2) { runwayDelta += 1.2; convictionDelta += 14; coachKey = `coach_r4_flexdown`; }
                        else { convictionDelta += 4; coachKey = `coach_r4_nothingtoflex`; }
                        break;
                    case `hold`:
                        runwayDelta -= 1.4; convictionDelta -= 10; coachKey = `coach_r4_hold`;
                        break;
                    case `layoff`:
                        // Pay the notice/severance tail you committed in R2 — expensive if you over-hired.
                        runwayDelta -= Math.min(2.0, ds.tailLiability / 80);
                        convictionDelta -= 4;
                        coachKey = ds.overHired ? `coach_r4_layoffheavy` : `coach_r4_layoff`;
                        break;
                    case `convert`:
                        // Locks platform knowledge — right if you'd hollowed the core, costly otherwise.
                        if (ds.coreOwned < 2) { deliveryDelta += 8; convictionDelta += 8; coachKey = `coach_r4_convert`; }
                        else { runwayDelta -= 0.5; convictionDelta -= 2; coachKey = `coach_r4_overconvert`; }
                        break;
                }
                // Stake the model on one metric for the investor.
                switch (d.metric) {
                    case `runway`: convictionDelta += 10; coachKey = (d.flex === `flexdown`) ? `coach_r4_investor` : coachKey; break;
                    case `revenue`: convictionDelta -= 4; break;
                    case `headcount`: convictionDelta -= 8; if (d.metric === `headcount`) coachKey = `coach_r4_headcount`; break;
                }
                if (d.pitchConviction >= 60) { convictionDelta += 5; }
                else if (d.pitchConviction <= 25) { convictionDelta -= 5; }

                summaryKey = (d.flex === `flexdown` && d.metric === `runway`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas, clamped.
            ds.runway = Math.round(Math.max(0, ds.runway + runwayDelta) * 10) / 10;
            ds.delivery = Math.max(0, Math.min(100, Math.round(ds.delivery + deliveryDelta)));
            ds.margin = Math.max(0, Math.min(60, Math.round(ds.margin + marginDelta)));
            ds.conviction = Math.max(0, Math.min(100, Math.round(ds.conviction + convictionDelta)));

            ds.runwayHistory.push(ds.runway);
            ds.deliveryHistory.push(ds.delivery);
            ds.convictionHistory.push(ds.conviction);
            // ── v1.1.0 fix: persist the composite where Express reporting reads it ──
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            const composite = this._composite(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;


            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                runway: ds.runway,
                runwayDelta: Math.round(runwayDelta * 10) / 10,
                delivery: ds.delivery,
                deliveryDelta: Math.round(deliveryDelta),
                margin: ds.margin,
                marginDelta: Math.round(marginDelta),
                conviction: ds.conviction,
                convictionDelta: Math.round(convictionDelta),
                score: composite,
                burn: ds.burn,
                empCount: ds.empCount,
                freeCount: ds.freeCount,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

