        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const runway = ds.runway;
            const delivery = Math.round(ds.delivery);
            const margin = Math.round(ds.margin);
            const conviction = Math.round(ds.conviction);

            // Composite: runway survival, delivery on the fixed date, margin vs target, thesis proven.
            const runwayScore = Math.max(0, Math.min(100, (runway / 9) * 100));
            const marginScore = Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 100));
            const composite = Math.round(
                runwayScore * 0.34 + delivery * 0.26 + marginScore * 0.14 + conviction * 0.26
            );

            const solvent = runway >= this.CLIFF;
            const delivers = delivery >= 60;
            const proven = conviction >= 60;
            const sank = runway < this.CLIFF || (ds.hollowedCore && delivery < 50);

            let performance = window.mySimulation.t(`grade_bet`);
            if (solvent && delivers && proven && composite >= 75) performance = window.mySimulation.t(`grade_proven`);
            else if (solvent && delivers) performance = window.mySimulation.t(`grade_delivered`);
            else if (ds.overHired && runway < this.CLIFF) performance = window.mySimulation.t(`grade_burned`);
            else if (ds.hollowedCore) performance = window.mySimulation.t(`grade_hollowed`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (solvent && delivers && proven) insights.push(window.mySimulation.t(`insight_proven`));
            else if (ds.overHired && runway < this.CLIFF) insights.push(window.mySimulation.t(`insight_overhired`));
            else if (ds.hollowedCore) insights.push(window.mySimulation.t(`insight_hollow`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (runway < this.CLIFF) insights.push(window.mySimulation.t(`insight_cliff`));
            else if (runway >= 8) insights.push(window.mySimulation.t(`insight_runway_strong`));
            if (margin < 30) insights.push(window.mySimulation.t(`insight_margin_low`));
            if (ds.tailLiability >= 60) insights.push(window.mySimulation.t(`insight_tail`));
            if (proven && solvent) insights.push(window.mySimulation.t(`insight_thesis`));

            return {
                runway: runway,
                delivery: delivery,
                margin: margin,
                conviction: conviction,
                solvent: solvent,
                delivers: delivers,
                proven: proven,
                sank: sank,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── v1.1.0 fix: persist composite score + localized completion debrief ──
        _composite(ds) {
            // Verbatim mirror of getPerformanceSummary()'s composite (no scoring change).
            const runway = ds.runway || 0;
            const delivery = Math.round(ds.delivery || 0);
            const margin = Math.round(ds.margin || 0);
            const conviction = Math.round(ds.conviction || 0);
            const runwayScore = Math.max(0, Math.min(100, (runway / 9) * 100));
            const marginScore = Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 100));
            return Math.round(runwayScore * 0.34 + delivery * 0.26 + marginScore * 0.14 + conviction * 0.26);
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const composite = (typeof s.composite === `number`) ? s.composite : 0;
            const grade = s.performance || ``;
            const held = !!(s.solvent && s.delivers);
            const runway = (s.runway != null) ? s.runway : 0;
            const delivery = (s.delivery != null) ? s.delivery : 0;
            const margin = (s.margin != null) ? s.margin : 0;
            const conviction = (s.conviction != null) ? s.conviction : 0;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const badgeClass = held ? `pe-cm-badge-pass` : `pe-cm-badge-miss`;
            const badgeText = held ? t(`cm_badge_beat`) : t(`cm_badge_missed`);

            const kpi = (label, val, sub, cls) => `
                <div class="pe-cm-kpi ${cls}">
                    <div class="pe-cm-kpi-val">${val}</div>
                    <div class="pe-cm-kpi-label">${label}</div>
                    <div class="pe-cm-kpi-sub">${sub}</div>
                </div>`;

            let insightHtml = ``;
            insights.forEach((it) => { insightHtml += `<li>${it}</li>`; });

            return `
                <div class="pe-cm">
                    <div class="pe-cm-scoreblock">
                        <div class="pe-cm-scorenum">${composite}<span class="pe-cm-scoremax">/100</span></div>
                        <div class="pe-cm-scorelabel">${t(`cm_score_label`)}</div>
                        <div class="pe-cm-grade">${grade}</div>
                        <span class="pe-cm-badge ${badgeClass}">${badgeText}</span>
                    </div>
                    <div class="pe-cm-kpis">
                        ${kpi(t(`runway_label`), runway + ` mo`, t(`runway_sub`), `pe-cm-k-runway`)}
                        ${kpi(t(`delivery_label`), delivery, t(`delivery_sub`), `pe-cm-k-delivery`)}
                        ${kpi(t(`margin_label`), margin + `%`, t(`margin_sub`), `pe-cm-k-margin`)}
                        ${kpi(t(`conviction_label`), conviction, t(`conviction_sub`), `pe-cm-k-conviction`)}
                    </div>
                    ${insightHtml ? `<div class="pe-cm-insights"><h6>${t(`cm_insights_title`)}</h6><ul>${insightHtml}</ul></div>` : ``}
                    <div class="pe-cm-footer">${t(`cm_footer`)}</div>
                </div>`;
        }

