            if (ds.hollowedCore && state.currentPeriod >= 2) return window.mySimulation.t(`hint_hollow`);
            if (ds.overHired && state.currentPeriod >= 2) return window.mySimulation.t(`hint_overhired`);
            if (ds.cashCrisis) return window.mySimulation.t(`hint_cash`);
            if (state.currentPeriod >= 3 && ds.conviction < 40) return window.mySimulation.t(`hint_conviction`);
            if (ds.runway >= 8 && ds.delivery >= 60 && ds.conviction >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

